// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(ok == (actor == c.owner()) && (ok ? c.owner() == newOwner : true));
    }
}
